using namespace std;

const int inf = 1e9;

void solve() {
    vector<int> a;
    {
        int n;
        cin >> n;

        map<int, int> cnt;
        while (n--) {
            int x;
            cin >> x;
            cnt[x]++;
        }

        for (auto const &[k, v]: cnt) {
            a.push_back(v);
        }
    }

    int n = a.size();
    vector<int> dp(n + 1, inf);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        vector<int> ndp = dp;

        for (int k = 1; k <= n; k++) {
            int nv = dp[k - 1] + a[i - 1];

            if (nv <= i - k) {
                ndp[k] = min(ndp[k], nv);
            }
        }

        dp = ndp;
    }

    int ans = n;
    while (dp[ans] >= inf) ans--;
    cout << n - ans << nl;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

    int T;
    cin >> T;
    while (T--) solve();
}

